    out = {'proj_single_trials':resp_diff, 'proj_tr':resp_diff_tr, 'proj_tr_mean':resp_diff_trMean, 'notes':dat['notes'], 'stim_ref':dat['stim_ref'], 'pos_from_prev':dat['pos_from_prev']}    
    return out    

