import numpy as np, os
from collections import defaultdict
# collect all behavior entries by raw key
entries = defaultdict(list)
for fn in sorted([f for f in os.listdir('/app/data/beh') if f.startswith('Beh_') and f.endswith('.npy')]):
    if fn == 'Beh_no_pretrain.npy' or fn == 'Beh_pretrain_on_grat_image.npy' or fn == 'Beh_pretrain_on_nat_image.npy':
        continue
    beh = np.load(os.path.join('/app/data/beh', fn), allow_pickle=True).item()
    for key, b in beh.items():
        raw = '_'.join(key.split('_')[:4])
        entries[raw].append((fn, key, b))

issues = []
for raw, vals in sorted(entries.items()):
    if len(vals) <= 1:
        continue
    ref = vals[0][2]
    for fn,key,b in vals[1:]:
        checks = {
            'ntrials': int(ref['ntrials']) == int(b['ntrials']),
            'WallName': np.array_equal(ref['WallName'], b['WallName']),
            'SoundPos': np.allclose(ref['SoundPos'], b['SoundPos'], equal_nan=True),
            'StartFr': np.allclose(ref['StartFr'], b['StartFr'], equal_nan=True),
            'EndFr': np.allclose(ref['EndFr'], b['EndFr'], equal_nan=True),
            'isRew': np.array_equal(ref['isRew'], b['isRew']),
        }
        if not all(checks.values()):
            issues.append((raw, vals[0][0], vals[0][1], fn, key, checks))
print('duplicated_raw_keys', sum(len(v)>1 for v in entries.values()))
print('issues_found', len(issues))
for item in issues[:20]:
    print(item)
