import numpy as np, os
from collections import defaultdict
canon_names = ['circle1','circle2','leaf1','leaf2','leaf3','leaf1_swap1','leaf1_swap2']
entries = defaultdict(list)
for fn in sorted([f for f in os.listdir('/app/data/beh') if f.startswith('Beh_') and f.endswith('.npy') and f not in {'Beh_no_pretrain.npy','Beh_pretrain_on_grat_image.npy','Beh_pretrain_on_nat_image.npy'}]):
    beh = np.load(os.path.join('/app/data/beh', fn), allow_pickle=True).item()
    for key, b in beh.items():
        parts = key.split('_')
        raw = '_'.join(parts[:5])
        entries[raw].append((fn, key, b))
missing = []
for raw, vals in sorted(entries.items()):
    local = {}
    ref = vals[0][2]
    for fn,key,b in vals:
        for wall, sid in zip(b['UniqWalls'], b['stim_id']):
            if np.isnan(sid):
                continue
            local[str(wall)] = canon_names[int(sid)]
    walls_present = set(map(str, np.unique(ref['WallName'])))
    not_mapped = sorted(walls_present - set(local.keys()))
    if not_mapped:
